// Bounded reproduction of the observed one-off production compression failure.
const fs=require('node:fs/promises');const path=require('node:path');const assert=require('node:assert/strict');const {chromium}=require(process.env.PDFPILOT_PLAYWRIGHT_MODULE||'playwright');
const base=process.argv[2]||'https://pdfpilot.net';const out=path.resolve(process.argv[3]||'docs/product-completion/qa-compress-timing-2026-10-04');const fixture=path.resolve(__dirname,'../tests/fixtures/product-qa/alpha.pdf');
(async()=>{await fs.mkdir(out,{recursive:true});const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});const results=[];try{const page=await browser.newPage({acceptDownloads:true,viewport:{width:1440,height:1000}});for(const mode of ['immediate','preview-ready'])for(let i=0;i<3;i++){const r={mode,attempt:i+1,console:[],errors:[],requests:[]};results.push(r);const onerror=e=>r.errors.push({message:e.message,stack:e.stack});const onconsole=async m=>{if(m.type()==='error')r.console.push({text:m.text(),location:m.location(),args:await Promise.all(m.args().map(a=>a.evaluate(x=>x instanceof Error?{message:x.message,stack:x.stack}:String(x)).catch(()=>'?')))});};const onrequest=req=>{const u=new URL(req.url());if(u.origin===base)r.requests.push({url:u.pathname,failure:req.failure()});};page.on('pageerror',onerror);page.on('console',onconsole);page.on('requestfailed',onrequest);await page.goto(base+'/compress-pdf',{waitUntil:'domcontentloaded'});await page.getByRole('button',{name:/Switch to (dark|light) mode/}).waitFor();await page.locator('input[type=file]').first().setInputFiles(fixture);if(mode==='preview-ready')await page.getByText('2 pages · 1.05 KB',{exact:true}).first().waitFor();const downloadPromise=page.waitForEvent('download',{timeout:60000}).catch(()=>null);const start=Date.now();await page.getByRole('button',{name:'Compress PDF',exact:true}).click();await page.waitForFunction(()=>/Your PDF is ready|Compression failed/.test(document.body.innerText),{},{timeout:60000});r.elapsedMs=Date.now()-start;r.ui=await page.locator('main').innerText();if(r.ui.includes('Your PDF is ready')){const d=await downloadPromise;assert.ok(d,'result must trigger real download');const file=path.join(out,`${mode}-${i+1}.pdf`);await d.saveAs(file);assert.deepEqual(await fs.readFile(file),await fs.readFile(fixture));r.bytes=(await fs.stat(file)).size;r.status='passed';await page.getByRole('button',{name:/^Start over$/i}).click();await page.locator('input[type=file]').first().waitFor({state:'attached'});r.reset=true;}else{r.status='processor-failed';await page.screenshot({path:path.join(out,`${mode}-${i+1}-failure.png`),fullPage:true});}page.off('pageerror',onerror);page.off('console',onconsole);page.off('requestfailed',onrequest);await fs.writeFile(path.join(out,'report.json'),JSON.stringify({base,results},null,2));console.log(mode,i+1,r.status,r.elapsedMs);}}finally{await browser.close();}if(results.some(x=>x.status!=='passed'))process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1;});
